import { createSlice, createAsyncThunk, PayloadAction } from '@reduxjs/toolkit';
import api from '../utils/api';
import { addMessageToCurrentSession } from './sessionSlice';
import { encryptMessage, getPrivateKey, decryptMessage } from '../utils/encryption';

interface User {
  id: string;
  pseudonym: string;
}

interface Message {
  id: string;
  sessionId: string;
  senderId: string;
  isAi: boolean;
  encryptedContent: string;
  encryptionMetadata: any;
  sentAt: string;
  content?: string;
  sender?: User;
}

interface MessageState {
  loading: boolean;
  error: string | null;
}

const initialState: MessageState = {
  loading: false,
  error: null,
};

// Send a message
export const sendMessage = createAsyncThunk(
  'messages/sendMessage',
  async (
    {
      sessionId,
      content,
      recipientPublicKey,
    }: {
      sessionId: string;
      content: string;
      recipientPublicKey: JsonWebKey;
    },
    { dispatch, rejectWithValue }
  ) => {
    try {
      // Encrypt the message
      const encrypted = await encryptMessage(content, recipientPublicKey);

      // Send the encrypted message to the API
      const response = await api.post('/messages', {
        sessionId,
        content, // For demonstration purposes, we're sending unencrypted content too
        encryptedContent: encrypted.encryptedMessage,
        encryptionMetadata: {
          encryptedKey: encrypted.encryptedKey,
          iv: encrypted.iv,
        },
      });

      // Add the user message to the current session
      dispatch(
        addMessageToCurrentSession({
          ...response.data.userMessage,
          content, // Include the decrypted content
          sender: { id: response.data.userMessage.senderId, pseudonym: 'You' },
        })
      );

      // Add the AI response to the current session
      dispatch(
        addMessageToCurrentSession({
          ...response.data.aiMessage,
          content: response.data.aiMessage.content, // AI response is already decrypted in our demo
          sender: { id: 'ai', pseudonym: 'Coco' },
        })
      );

      return response.data;
    } catch (error: any) {
      return rejectWithValue(error.response?.data?.message || 'Failed to send message');
    }
  }
);

// Fetch messages for a session
export const fetchMessages = createAsyncThunk(
  'messages/fetchMessages',
  async (sessionId: string, { rejectWithValue }) => {
    try {
      const response = await api.get(`/messages/${sessionId}`);

      // In a real app, we would decrypt messages here
      const privateKey = getPrivateKey();
      if (!privateKey) {
        return rejectWithValue('Private key not found');
      }

      const decryptedMessages = await Promise.all(
        response.data.map(async (message: Message) => {
          // For demonstration, we're assuming we can decrypt in this way
          // In a real app, this would be more complex
          if (!message.isAi) {
            try {
              const decrypted = await decryptMessage(
                message.encryptedContent,
                message.encryptionMetadata.encryptedKey,
                message.encryptionMetadata.iv,
                privateKey
              );
              return { ...message, content: decrypted };
            } catch (error) {
              console.error('Failed to decrypt message:', error);
              return { ...message, content: '[Encrypted]' };
            }
          }
          // For AI messages, we'll just use the encryptedContent directly in this demo
          return { ...message, content: message.encryptedContent };
        })
      );

      return decryptedMessages;
    } catch (error: any) {
      return rejectWithValue(error.response?.data?.message || 'Failed to fetch messages');
    }
  }
);

const messageSlice = createSlice({
  name: 'messages',
  initialState,
  reducers: {
    clearMessageError: (state) => {
      state.error = null;
    },
  },
  extraReducers: (builder) => {
    builder
      // Send message
      .addCase(sendMessage.pending, (state) => {
        state.loading = true;
        state.error = null;
      })
      .addCase(sendMessage.fulfilled, (state) => {
        state.loading = false;
      })
      .addCase(sendMessage.rejected, (state, action) => {
        state.loading = false;
        state.error = action.payload as string;
      })
      // Fetch messages
      .addCase(fetchMessages.pending, (state) => {
        state.loading = true;
        state.error = null;
      })
      .addCase(fetchMessages.fulfilled, (state) => {
        state.loading = false;
      })
      .addCase(fetchMessages.rejected, (state, action) => {
        state.loading = false;
        state.error = action.payload as string;
      });
  },
});

export const { clearMessageError } = messageSlice.actions;
export default messageSlice.reducer;
